LOG2E = 1.4426950408889634


def _convert_attn_sink_to_log2(sink: Optional[torch.Tensor]) -> Optional[torch.Tensor]:
    if sink is None:
        return None
    return sink.to(dtype=torch.float32) * LOG2E


