@ttfs.triton_jitx_kernel
def sparse_attn_fwd_varlen_tma_kernel(args: AttentionArgs, BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr):
    bh_id = tl.program_id(1)
    seq_id = tl.program_id(0)
    h_id = bh_id % args.tensors.H_kv
    tm = args.tensors
    tm = tm.offset_all_tensor("H_kv,S_qo,H_kv_mul_D,H_kv_mul_dv", (h_id, seq_id, h_id * tm.D_total, h_id * tm.D_v))
    q_desc = tm.get_external_tma_block_desc("q", "S,GQA,D")
    if args.has_tma_gather:
        k_desc = tm.get_external_tma_block_desc("k", "S,H_kv_mul_D")
        v_desc = tm.get_external_tma_block_desc("v", "S,H_kv_mul_dv")
    else:
        k_desc = tm.get_offseted_block_desc("k", "S,H_kv_mul_D", [BLOCK_N, tm.D])
        v_desc = tm.get_offseted_block_desc("v", "S,H_kv_mul_dv", [BLOCK_N, tm.D_v])

    has_remain: tl.constexpr = tm.D_remain != 0

    if has_remain:
        q_remain_desc = tm.get_external_tma_block_desc("q_remain", "S,GQA,D").offset(D=tm.D)
        if args.has_tma_gather:
            k_remain_desc = tm.get_external_tma_block_desc("k_remain", "S,H_kv_mul_D").offset(H_kv_mul_D=tm.D)
        else:
            k_remain_desc = tm.get_offseted_block_desc("k_remain", "S,H_kv_mul_D", [BLOCK_N, tm.D_remain]).offset(H_kv_mul_D=tm.D)
    else:
        q_remain_desc = None
        k_remain_desc = None
    # kv_inds shape is [seqlen, topk], we will offset it by seq_id, so we need to use int64 for offset.
    kv_inds_desc = tm.get_offseted_block_desc("kv_inds", "topk", [BLOCK_N], cast_offset_to_64bit=args.need_i64)
    q = q_desc.tma_load([0, 0, 0]).reshape(BLOCK_M * tm.GQA, tm.D)
    if q_remain_desc is not None:
        q_remain = q_remain_desc.tma_load([0, 0, 0]).reshape(BLOCK_M * tm.GQA, tm.D_remain)
    if tm.sink.is_valid_desc().value:
        sink = tm.get_offseted_block_desc("sink", "GQA", [tm.GQA]).masked_load()
        m_i = tl.zeros([BLOCK_M * tm.GQA], dtype=tl.float32).reshape(BLOCK_M, tm.GQA) + sink[None, :]
        m_i = m_i.reshape(BLOCK_M * tm.GQA)
    else:
        m_i = tl.zeros([BLOCK_M * tm.GQA], dtype=tl.float32) - float("inf")

    l_i = tl.zeros([BLOCK_M * tm.GQA], dtype=tl.float32) + 1.0
    acc = tl.zeros([BLOCK_M * tm.GQA, tm.D_v], dtype=tl.float32)
    QK_SCALE: tl.constexpr = args.sm_scale * 1.44269504  # 1/log(2)
    offs_n = k_desc.get_blocked_offset_base("S")
    if tm.cu_seqlen_k_start is not None and tm.cu_seqlen_k_end is not None:
        start = tl.load(tm.cu_seqlen_k_start + seq_id).to(tl.int32)
        end = tl.load(tm.cu_seqlen_k_end + seq_id).to(tl.int32)
        num_kv_inds = end - start
    else:
        num_kv_inds = min(tm.topk, tm.S_kv)
    num_kv_blocks = tl.cdiv(num_kv_inds, BLOCK_N)
    kv_inds_ptrs = kv_inds_desc.get_blocked_ptrs(use_i64=args.need_i64)
    offs_n = tl.arange(0, BLOCK_N)
    # add_offset_to_inds = False: means topk inds is global when varlen.
    # triton warp_specialize currently don't support pointer based gather.
    for kv_idx in tl.range(num_kv_blocks, warp_specialize=args.has_tma_gather):
        # assume at least one valid kv in this block, the invalid ones will be masked out later.
        # assume kv inds is global
        kv_inds = tl.load(kv_inds_ptrs + kv_idx * BLOCK_N, mask=offs_n < num_kv_inds, other=-1)
        kv_inds_mask = kv_inds >= 0
        # tl.device_print("kv_inds", kv_inds)
        kv_inds_masked = tl.where(kv_inds_mask, kv_inds, 0)
        k = k_desc.gather([kv_inds_masked, 0], add_offset_to_inds=False, use_i64=args.need_i64).T
        if k_remain_desc is not None:
            k_remain = k_remain_desc.gather([kv_inds_masked, 0], add_offset_to_inds=False, use_i64=args.need_i64).T

        # k = tl.load(k_ptrs).T
        qk = tl.dot(q, k)
        if q_remain_desc is not None:
            qk = tl.dot(q_remain, k_remain, acc=qk)
        qk = tl.where(kv_inds_mask[None, :], qk, float("-inf"))

        m_ij = tl.maximum(m_i, tl.max(qk, 1) * QK_SCALE)
        qk = qk * QK_SCALE - m_ij[:, None]
        p = tl.math.exp2(qk)
        # -- compute correction factor
        alpha = tl.math.exp2(m_i - m_ij)
        l_ij = tl.sum(p, 1)
        acc = acc * alpha[:, None]
        # prepare p and v for the dot
        v = v_desc.gather([kv_inds_masked, 0], add_offset_to_inds=False, use_i64=args.need_i64)
        # v = tl.load(v_ptrs)
        p = p.to(tl.bfloat16)
        # note that this non transposed v for FP8 is only supported on Blackwell
        acc = tl.dot(p, v, acc)
        # update m_i and l_i
        # place this at the end of the loop to reduce register pressure
        l_i = l_i * alpha + l_ij
        m_i = m_ij
        offs_n += BLOCK_N
    o_desc = tm.get_offseted_block_desc("o", "S,GQA,D", [BLOCK_M, tm.GQA, tm.D_v], cast_offset_to_64bit=args.need_i64)
    lse_desc = tm.get_offseted_block_desc("lse", "GQA,S", [tm.GQA, BLOCK_M])

    m_i += tl.math.log2(l_i)
    acc = acc / l_i[:, None]
    lse_desc.masked_store(m_i.reshape(BLOCK_M, tm.GQA).T)
    o_desc.masked_store(acc.to(tl.bfloat16).reshape(BLOCK_M, tm.GQA, tm.D_v), use_i64=args.need_i64)


def is_sparse_attn_need_i64(
    S_qo: int,
    S_kv: int,
    topk: int,
    H_kv: int,
    GQA: int,
    total_d: int,
    D_v: int,
    is_q_tma: bool,
    is_o_tma: bool,
) -> bool:
    int32_offset_count_limit = 2**31
    kv_inds_is_overflow = S_qo * topk > int32_offset_count_limit
    if is_q_tma:
        q_is_overflow = False
    else:
        q_is_overflow = S_qo * H_kv * GQA * total_d > int32_offset_count_limit
    if is_o_tma:
        o_is_overflow = False
    else:
        o_is_overflow = S_qo * H_kv * GQA * D_v > int32_offset_count_limit
    k_is_overflow = S_kv * H_kv * total_d > int32_offset_count_limit
    v_is_overflow = S_kv * H_kv * D_v > int32_offset_count_limit

    return (
        kv_inds_is_overflow
        or q_is_overflow
        or o_is_overflow
        or k_is_overflow
        or v_is_overflow
    )


def sparse_attn_fwd_varlen(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
        kv_inds: torch.Tensor,
        cu_seqlen_q: Optional[torch.Tensor] = None, 
        cu_seqlen_kv: Optional[torch.Tensor] = None, 
        sink: Optional[torch.Tensor] = None,
        max_seqlen_q: Optional[int] = None, 
        max_seqlen_k: Optional[int] = None,
        cu_seqlen_k_start: Optional[torch.Tensor] = None,
        cu_seqlen_k_end: Optional[torch.Tensor] = None,
        sm_scale: Optional[float] = None,
        disable_tma_gather: bool = False,
        force_gluon_kernel: Optional[bool] = None):
    # cu_seqlen_q: accumulated seqlen of q, shape [B + 1], e.g. [0, 256, 384] for seqlen [256, 128]
    if max_seqlen_q is None:
        max_seqlen_q = q.shape[1]
    if max_seqlen_k is None:
        max_seqlen_k = k.shape[1]
    if cu_seqlen_q is None:
        # create a trivial cu_seqlen_q for demonstration, which means all sequences have same length.
        cu_seqlen_q = torch.arange(0, (q.shape[0] + 1) * max_seqlen_q, step=max_seqlen_q, device=q.device, dtype=torch.int32)
    if cu_seqlen_kv is None:
        cu_seqlen_kv = torch.arange(0, (k.shape[0] + 1) * max_seqlen_k, step=max_seqlen_k, device=k.device, dtype=torch.int32)
    if cu_seqlen_q.numel() != cu_seqlen_kv.numel():
        raise ValueError("cu_seqlen_q and cu_seqlen_kv must have the same length")
    if k.dtype == torch.float32:
        k = k.to(q.dtype)
    if v.dtype == torch.float32:
        v = v.to(q.dtype)

    topk = kv_inds.shape[-1]
    _, S_qo, H_q, total_d = q.shape
    _, S_kv, H_kv, total_d = k.shape
    D_v = v.shape[-1]
    B = cu_seqlen_q.numel() - 1
    num_seq = cu_seqlen_q.shape[0] - 1
    GQA = H_q // H_kv
    D = 1 << (total_d.bit_length() - 1)
    D_remain = total_d - D
    if D_remain != 0 and D_remain & (D_remain - 1):
        raise ValueError(
            f"indexer_kl_fwd only supports head dims that split into two power-of-two chunks, got {total_d}"
        )

    S_kv = k.shape[1]
    assert k.shape == (1, S_kv, H_kv, total_d)
    assert v.shape == (1, S_kv, H_kv, D_v)
    if sm_scale is None:
        sm_scale = 1.0 / math.sqrt(q.size(-1))
    o = torch.zeros((1, S_qo, H_kv * GQA, D_v), device=q.device, dtype=torch.bfloat16)
    lse = torch.zeros((1, H_q, S_qo), device=q.device, dtype=torch.float32)
    BLOCK_M = 1 
    BLOCK_N = 64 if D_remain != 0 else 128
    q = q.view(S_qo, H_kv, GQA, -1)
    k = k.view(S_kv, -1)
    v = v.view(S_kv, -1)
    has_tma_gther = check_has_tma_gather() and not disable_tma_gather
    has_tma_gther = False
    arch = torch.cuda.get_device_capability()

    use_gluon = GQA >= 8 and D_v >= 64 and arch[0] == 9
    use_gluon = False
    if force_gluon_kernel is not None:
        if force_gluon_kernel:
            assert use_gluon
        use_gluon = force_gluon_kernel
    NUM_Q_SPLIT = 1
    if use_gluon:
        # BLOCK_N = min(BLOCK_N, 128)
        NUM_Q_SPLIT = 2 if BLOCK_N > 128 else 2

    with ttfs.tensor_desc_creator_dispatch(use_gluon, enable_cache=True):
        tdesc_q = SparseAttnDecodeSymbols.q.create_tma_desc(q)
        if has_tma_gther:
            raise NotImplementedError
            tdesc_k = SparseAttnDecodeSymbols.k_tma_gather.create_tma_desc(k)
            tdesc_v = SparseAttnDecodeSymbols.v_tma_gather.create_tma_desc(v)
        else:
            tdesc_k = SparseAttnDecodeSymbols.k.create_desc(k)
            tdesc_v = SparseAttnDecodeSymbols.v.create_desc(v)
        if D_remain != 0:
            tdesc_q_remain = SparseAttnDecodeSymbols.q_remain.create_tma_desc(q)
            if has_tma_gther:
                tdesc_k_remain = SparseAttnDecodeSymbols.k_remain_tma_gather.create_tma_desc(k)
            else:
                tdesc_k_remain = SparseAttnDecodeSymbols.k_remain.create_desc(k)
        else:
            tdesc_q_remain = ttfs.TensorDesc.empty_host()
            tdesc_k_remain = ttfs.TensorDesc.empty_host()
        tdesc_o = SparseAttnDecodeSymbols.oT.create_desc(o.view(S_qo, H_kv, GQA, D_v))
        tdesc_lse = SparseAttnDecodeSymbols.lse.create_desc(lse.view(H_kv, GQA, -1))
        tdesc_kv_inds = SparseAttnDecodeSymbols.kv_inds.create_desc(kv_inds.view(S_qo, topk))
        if sink is not None:
            if sink.shape != (H_q,):
                raise ValueError(f"sink must have shape [H_q], got {tuple(sink.shape)}")
            assert sink.is_contiguous(), "sink must be contiguous"
            sink_log2 = _convert_attn_sink_to_log2(sink)
            assert sink_log2 is not None
            tdesc_sink = SparseAttnDecodeSymbols.sink.create_desc(sink_log2.view(H_kv, GQA))
        else:
            tdesc_sink = ttfs.TensorDesc.empty_host()

        tensors = AttentionManager(
            q=tdesc_q,
            k=tdesc_k,
            v=tdesc_v,
            o=tdesc_o,
            q_remain=tdesc_q_remain,
            k_remain=tdesc_k_remain,
            kv_inds=tdesc_kv_inds,
            lse=tdesc_lse,
            sink=tdesc_sink,
            S_qo=S_qo,
            S_kv=S_kv,
            B=-1, # unused
            topk=topk,
            H_kv=H_kv,
            GQA=GQA,
            H_kv_mul_D=H_kv * total_d,
            H_kv_mul_dv=H_kv * D_v,
            D=D,
            D_total=total_d,
            D_remain=D_remain,
            D_v=D_v,
            BLOCK_M=BLOCK_M,
            BLOCK_N=BLOCK_N,
            cu_seqlen_q=cu_seqlen_q,
            cu_seqlen_kv=cu_seqlen_kv,
            cu_seqlen_k_start=cu_seqlen_k_start,
            cu_seqlen_k_end=cu_seqlen_k_end
        )
        # TODO use tma for o?
        need_i64 = is_sparse_attn_need_i64(S_qo, S_kv, topk, H_kv, GQA, total_d, D_v, True, False)
        num_sm = get_num_sms()

        args = AttentionArgs(tensors=tensors, sm_scale=sm_scale, has_tma_gather=has_tma_gther, need_i64=need_i64,
            num_q_split=NUM_Q_SPLIT, num_sm=num_sm
        )
        grid = (num_sm,) if use_gluon else (div_up(S_qo, BLOCK_M), H_kv)
        if use_gluon:
            # naivert: the source fixes use_gluon = False; only the Triton kernel is copied.
            raise NotImplementedError("naivert copies only the Triton sparse-attention prefill kernel")
        else:
            ker = sparse_attn_fwd_varlen_tma_kernel[grid](args=args, BLOCK_M=BLOCK_M, BLOCK_N=BLOCK_N, num_stages=2)
    return o, lse
